import type { WixDataGetOptions } from './types'

/**
 * Options builder for get operations.
 *
 * Use this builder to configure get behavior such as hooks suppression,
 * app-specific options, language, consistency, selected
 * fields, references, and field groups.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataGetOptionsBuilder {
  /**
   * Sets whether to suppress get hooks.
   *
   * When `true`, the get operation runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataGetOptionsBuilder
  /**
   * Sets whether to include draft items when retrieving an item.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataGetOptionsBuilder
  /**
   * Sets app-specific options for the get operation.
   */
  withAppOptions(value: Record<string, any>): WixDataGetOptionsBuilder
  /**
   * Sets the language used for the get operation.
   */
  withLanguage(value: string): WixDataGetOptionsBuilder
  /**
   * Sets whether the get operation uses a consistent read.
   */
  withConsistentRead(value: boolean): WixDataGetOptionsBuilder
  /**
   * Sets the fields to include in the returned item.
   */
  withFields(...value: string[]): WixDataGetOptionsBuilder
  /**
   * Sets referenced fields to include in the returned item.
   */
  withIncludeReferences(
    value: { field: string; limit?: number }[]
  ): WixDataGetOptionsBuilder
  /**
   * Sets the field groups to include in the returned item.
   */
  withIncludeFieldGroups(...value: string[]): WixDataGetOptionsBuilder
  /**
   * Builds the get options object.
   */
  build(): WixDataGetOptions
}

class WixDataGetOptionsBuilderImpl implements WixDataGetOptionsBuilder {
  constructor(private readonly options: WixDataGetOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataGetOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataGetOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withAppOptions(value: Record<string, any>): WixDataGetOptionsBuilder {
    return this.copy({ appOptions: { ...value } })
  }

  withLanguage(value: string): WixDataGetOptionsBuilder {
    return this.copy({ language: value })
  }

  withConsistentRead(value: boolean): WixDataGetOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  withFields(...value: string[]): WixDataGetOptionsBuilder {
    return this.copy({ fields: [...value] })
  }

  withIncludeReferences(
    value: { field: string; limit?: number }[]
  ): WixDataGetOptionsBuilder {
    return this.copy({
      includeReferences: value.map((includeReference) => ({
        ...includeReference,
      })),
    })
  }

  withIncludeFieldGroups(...value: string[]): WixDataGetOptionsBuilder {
    return this.copy({ includeFieldGroups: [...value] })
  }

  build(): WixDataGetOptions {
    return {
      ...this.options,
      ...(this.options.appOptions
        ? { appOptions: { ...this.options.appOptions } }
        : {}),
      ...(this.options.fields ? { fields: [...this.options.fields] } : {}),
      ...(this.options.includeReferences
        ? {
            includeReferences: this.options.includeReferences.map(
              (includeReference) => ({ ...includeReference })
            ),
          }
        : {}),
      ...(this.options.includeFieldGroups
        ? { includeFieldGroups: [...this.options.includeFieldGroups] }
        : {}),
    }
  }

  private copy(options: WixDataGetOptions): WixDataGetOptionsBuilder {
    return new WixDataGetOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new get options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a get options builder"
 * import { items, GetOptionsBuilder } from '@wix/data'
 *
 * const options = GetOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withAppOptions({ key: 'value' })
 *   .withLanguage('es')
 *   .withConsistentRead(true)
 *   .withFields('_id', 'foo')
 *   .withIncludeReferences([{ field: 'author', limit: 1 }])
 *   .withIncludeFieldGroups('group-a')
 *   .build()
 *
 * const item = await items.get('myCollection', 'someId', options)
 * ```
 */
export const GetOptionsBuilder: () => WixDataGetOptionsBuilder = () =>
  new WixDataGetOptionsBuilderImpl()
